#!/usr/bin/env python3
#
# plot_population.py - draws a line plot of population by year.
#
# AI acknowledgment: this plotting script was generated by an AI assistant
# (Claude, Anthropic), as the assignment allows for the plotting part.
# The (year,population) data is NOT read here from the ABS file: server.sh
# extracts it from STE_1.csv with bash/awk and writes population_data.csv.
#
# usage: python3 plot_population.py <data.csv> <output.png> [title]
#   data.csv has a header line, then one "year,population" pair per line.

import sys

import matplotlib
matplotlib.use("Agg")  # no screen in the container: draw straight to a file
import matplotlib.pyplot as plt
from matplotlib.ticker import FuncFormatter


def fail(message):
    print("error: " + message, file=sys.stderr)
    sys.exit(1)


if len(sys.argv) not in (3, 4):
    fail("usage: plot_population.py <data.csv> <output.png> [title]")

dataFile = sys.argv[1]
outFile = sys.argv[2]
title = sys.argv[3] if len(sys.argv) == 4 else "Population by year"

years = []
population = []
try:
    with open(dataFile) as f:
        next(f, None)  # skip the "year,population" header
        for lineNo, line in enumerate(f, start=2):
            line = line.strip()
            if not line:
                continue
            parts = line.split(",")
            if len(parts) != 2:
                fail("%s line %d: expected 'year,population', got '%s'" % (dataFile, lineNo, line))
            try:
                years.append(int(parts[0]))
                population.append(int(parts[1]))
            except ValueError:
                fail("%s line %d: not a number: '%s'" % (dataFile, lineNo, line))
except OSError as e:
    fail("cannot read %s: %s" % (dataFile, e.strerror))

if len(years) < 2:
    fail("need at least 2 data points to plot, got %d" % len(years))

fig, ax = plt.subplots(figsize=(8, 5))
ax.plot(years, population, marker="o", linewidth=2)
for x, y in zip(years, population):
    ax.annotate("{:,}".format(y), (x, y), textcoords="offset points",
                xytext=(0, 8), ha="center", fontsize=8)
ax.set_title(title)
ax.set_xlabel("Year")
ax.set_ylabel("Population")
ax.set_xticks(years)
ax.yaxis.set_major_formatter(FuncFormatter(lambda v, _: "{:,.0f}".format(v)))
ax.grid(True, alpha=0.3)
fig.tight_layout()

try:
    fig.savefig(outFile, dpi=100)
except OSError as e:
    fail("cannot write %s: %s" % (outFile, e.strerror))
